"""
    Iterates through a list of dictionaries and, based on the inserted key name, extracts that data.

    :param: ls_of_dictionaries: a list of dictionaries
    :param: key_name: a string with ('') that indexes which set of the dictionary you want to extract

    :returns: list with the specified (keyed) datatype


    """
def extract_from_dictionary(ls_of_dictionaries: Any, key_name: Any) -> object {
    partic_name = [];
    data_element = [];
    for (index, dictionary) in enumerate(ls_of_dictionaries) {
        data = dictionary[key_name];
        partic_name = dictionary['partic_number'];
        data_element.append(data);
    }
    return data_element;
}

test_blocks:
test "t0" {
    assert (
        extract_from_dictionary(
            [
                {'partic_number': 'a', 'pH': 1},
                {'partic_number': 'b', 'pH': 2},
                {'partic_number': 'c', 'pH': 3}
            ],
            'pH'
        )
        == [1, 2, 3]
    );;
}

test "t1" {
    assert (
        extract_from_dictionary(
            [
                {'partic_number': 'a', 'pH': 1},
                {'partic_number': 'b', 'pH': 2},
                {'partic_number': 'c', 'pH': 3}
            ],
            'partic_number'
        )
        == ['a', 'b', 'c']
    );;
}

test "t2" {
    assert (
        extract_from_dictionary(
            [
                {"partic_number": "1", "a": 1, "b": 2},
                {"partic_number": "2", "a": 2, "b": 4}
            ],
            "b"
        )
        == [2, 4]
    );;
}

test "t3" {
    assert (
        extract_from_dictionary(
            [
                {'partic_number': 100, 'partic_mass': 200.0},
                {'partic_number': 200, 'partic_mass': 300.0},
                {'partic_number': 300, 'partic_mass': 400.0}
            ],
            'partic_mass'
        )
        == [200.0, 300.0, 400.0]
    );;
}

test "t4" {
    assert (
        extract_from_dictionary(
            [
                {"partic_number": "1", "a": 1, "b": 2},
                {"partic_number": "2", "a": 2, "b": 4}
            ],
            "a"
        )
        == [1, 2]
    );;
}

test "t5" {
    assert (
        extract_from_dictionary(
            [
                {"partic_number": "1", "a": 1, "b": 2},
                {"partic_number": "2", "a": 2, "b": 4}
            ],
            "partic_number"
        )
        == ["1", "2"]
    );;
}

test "t6" {
    assert (
        extract_from_dictionary(
            [
                {'partic_number': 100, 'partic_mass': 200.0},
                {'partic_number': 200, 'partic_mass': 300.0},
                {'partic_number': 300, 'partic_mass': 400.0}
            ],
            'partic_number'
        )
        == [100, 200, 300]
    );;
}
